* {
  margin: 0;
  padding: 0;
  font-family: "Arial";
}
html,
#window {
  background: #fff;
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
  width: 100%;
}
#windowContainer {
  width: 100%;
  height: 100%;
  position: absolute;
}
.top {
  -moz-window-dragging: drag;
  padding-top: 6px;
  background: #A0A2A4;
}
.top .backforward {
  background: linear-gradient(to bottom, #68696c, #eeeeee);
  position: absolute;
  z-index: 10;
  top: -12px;
  left: 80px;
  border: 1px solid #cccccc;
  border-radius: 66px;
  width: 66px;
  height: 66px;
  vertical-align: center;
}
.top .backforward span {
  position: absolute;
  color: #3B3B3B;
  line-height: 80px;
  font-weight: 300;
  opacity: 0.3;
}
.top .backforward span:not([disabled]) {
  opacity: 0.6;
}
.top .backforward span:not([disabled]):hover {
  color: #3B3B3B;
  opacity: 1;
}
.top .backforward .back {
  border-right: 1px solid #7E7F83;
  font-size: 60px;
  left: 12px;
  padding-right: 4px;
  top: -11px;
}
.top .backforward .forward {
  top: -9px;
  right: 10px;
  font-size: 35px;
}
.mainContainer {
  display: flex;
  flex-direction: row;
  flex-grow: 1;
  width: 100%;
}
.mainContainer .tabContainer {
  flex-grow: 1;
  position: relative;
}
.mainContainer > div.tabs {
  width: 180px;
  overflow-y: scroll;
}
.frameWrapper {
  height: 100%;
  width: 100%;
  z-index: 2;
  position: absolute;
  top: 0;
  left: 0;
  -webkit-user-select: none;
}
.frameWrapper webview {
  background-color: #fff;
  border: 0;
  height: 100%;
  width: 100%;
}
.frameWrapper .webviewContainer {
  height: 100%;
  width: 100%;
}
.frameWrapper .webviewContainer.isPreview {
  opacity: 0.5;
}
.frameWrapper:not(.isActive) {
  z-index: 1;
}
.frameWrapper:not(.isActive).isPreview {
  background: gray;
  z-index: 3;
}
body.fullScreen .frameWrapper.isActive {
  z-index: 10000;
}
/* The fullscreen notice is shown above the fullscreen element */
body.fullScreen .banner {
  position: absolute;
  z-index: 10001;
  top: 0;
  opacity: 1;
  transition: opacity 2s ease-in-out;
}
body.fullScreen .banner.fade {
  opacity: 0;
}
[draggable] {
  -webkit-user-select: none;
}
.link {
  color: #0099CC;
  cursor: pointer;
  text-decoration: underline;
}
a {
  cursor: pointer;
}
.topLevelEndButtons {
  position: absolute;
  top: 5px;
  right: 0;
}
