span.browserButton {
  cursor: default;
  display: inline-block;
  line-height: 28px;
  width: 30px;
  height: 30px;
  font-size: 20px;
  color: #3B3B3B;
  border-radius: 30px;
  margin: 0 3px;
  text-align: center;
  transition: 0.1s opacity, 0.1s background;
}
span.browserButton:not([disabled]):hover {
  color: black;
}
span.browserButton[disabled] {
  opacity: 0.25;
  pointer-events: none;
}
span.browserButton.smallButton {
  line-height: 18px;
  width: 18px;
  height: 18px;
  font-size: 12px;
}
span.browserButton.newFrameButton {
  font-family: helvetica;
  width: 26px;
  vertical-align: middle;
}
