.dialog {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 100%;
  z-index: 313;
  display: flex;
  justify-content: center;
  align-items: center;
  background: rgba(0, 0, 0, 0.15);
}
.dialog menu {
  height: 300px;
  width: 500px;
  flex: 0 0 auto;
  background: #3a3a3a;
  color: #fff;
  font-size: 13px;
  display: flex;
  flex-direction: column;
}
.dialog menu.contextMenuWithPosition {
  height: auto;
  padding: 10px;
  width: auto;
}
.dialog menu.contextMenuWithPosition span {
  width: 250px;
}
.dialog menu h1 {
  border-bottom: 1px solid #444444;
  margin-bottom: 10px;
  padding-bottom: 10px;
  padding: 10px 14px;
  font-size: 18px;
  font-weight: normal;
}
.dialog menu p,
.dialog menu li,
.dialog menu form {
  padding: 10px 14px;
}
.dialog menu span {
  display: block;
  box-sizing: border-box;
  width: 100%;
  padding: 10px 14px;
}
.dialog menu span + span {
  border-top: 1px solid #444444;
}
.dialog menu span.option:hover {
  background-color: #0076FF;
  cursor: pointer;
}
.dialog menu section.body {
  border-bottom: 1px solid #444444;
  flex: 1 1 auto;
}
.dialog menu section.body input {
  width: 100%;
}
.dialog menu section.body ul {
  list-style-type: none;
}
.dialog menu section.body ul.select li:hover {
  background: #008FFF;
  cursor: pointer;
}
